  "Choose copy options next. Only successfully copied and verified members are removed from the working archive. Save archive to commit the removal.":
      [
        "Als Nächstes Kopieroptionen wählen. Nur erfolgreich kopierte und geprüfte Elemente werden aus dem Arbeitsarchiv entfernt. „Archiv speichern“ bestätigt die Entfernung.",
        "Choisissez ensuite les options de copie. Seuls les éléments copiés et vérifiés sont retirés de l’archive de travail. Enregistrez l’archive pour valider le retrait.",
        "Elija ahora las opciones de copia. Solo los elementos copiados y verificados se quitan del archivo de trabajo. Guarde el archivo comprimido para confirmar la eliminación.",
        "Escolha as opções de cópia a seguir. Apenas itens copiados e verificados são removidos do arquivo de trabalho. Salve o arquivo compactado para confirmar a remoção.",
        "接下来选择复制选项。只有成功复制并通过验证的成员才会从工作压缩包中移除。保存压缩包后才会提交移除。",
        "次にコピーオプションを選択します。コピーと検証に成功した項目だけを作業中のアーカイブから除きます。削除を確定するにはアーカイブを保存してください。",
        "다음으로 복사 옵션을 선택하세요. 복사 및 검증에 성공한 항목만 작업 중인 압축 파일에서 제거됩니다. 제거를 확정하려면 압축 파일을 저장하세요.",
        "اختر خيارات النسخ بعد ذلك. تُزال من نسخة الأرشيف العاملة العناصر المنسوخة والمتحقق منها بنجاح فقط. احفظ الأرشيف لتثبيت الإزالة.",
