  "Each part and the original file receive a SHA-256 checksum. Keep the .split.json manifest with the numbered parts. Cancelling keeps completed parts and an incomplete manifest.":
      [
        "Jeder Teil und die Originaldatei erhalten eine SHA-256-Prüfsumme. Die .split.json-Prüfliste bei den nummerierten Teilen aufbewahren. Abbrechen behält fertige Teile und eine unvollständige Prüfliste.",
        "Chaque partie et le fichier d’origine reçoivent une somme SHA-256. Gardez le manifeste .split.json avec les parties numérotées. L’annulation conserve les parties terminées et un manifeste incomplet.",
        "Cada parte y el archivo original reciben una suma SHA-256. Guarde el manifiesto .split.json con las partes numeradas. Cancelar conserva las partes completadas y un manifiesto incompleto.",
        "Cada parte e o arquivo original recebem uma soma SHA-256. Guarde o manifesto .split.json com as partes numeradas. Cancelar mantém as partes concluídas e um manifesto incompleto.",
        "每个分块和原始文件都会生成 SHA-256 校验和。请将 .split.json 清单与编号分块一起保存。取消后会保留已完成分块和不完整清单。",
        "各パートと元のファイルに SHA-256 チェックサムを作成します。.split.json マニフェストを番号付きパートと一緒に保管してください。中止すると完了したパートと未完了のマニフェストが残ります。",
        "각 조각과 원본 파일에 SHA-256 체크섬을 생성합니다. .split.json 매니페스트를 번호가 있는 조각과 함께 보관하세요. 취소하면 완료된 조각과 미완료 매니페스트가 유지됩니다.",
        "يحصل كل جزء والملف الأصلي على مجموع SHA-256. احتفظ ببيان .split.json مع الأجزاء المرقمة. يُبقي الإلغاء الأجزاء المكتملة وبيانًا غير مكتمل.",
