        "検索結果、インポートしたリスト、選択ファイルを元のアカウントとともに保持します。「開く」は保存パスを確認し、再検索は保存済みクエリを使用します。",
        "검색 결과, 가져온 목록, 선택 파일을 원래 계정과 함께 유지합니다. 열기는 저장된 경로를 확인하며 다시 검색은 저장된 쿼리를 사용합니다.",
