  "TC ranges: [N1-5]. DC ranges: [N1:5] or [N1,5]. [meta:artist] uses metadata already supplied by the source; unavailable fields block the preview. The dialect is stored with presets.":
      [
        "TC-Bereiche: [N1-5]. DC-Bereiche: [N1:5] oder [N1,5]. [meta:artist] nutzt Metadaten der Quelle; fehlende Felder blockieren die Vorschau. Die Syntax wird mit Vorlagen gespeichert.",
        "Plages TC : [N1-5]. Plages DC : [N1:5] ou [N1,5]. [meta:artist] utilise les métadonnées de la source ; les champs absents bloquent l’aperçu. La syntaxe est enregistrée avec les préréglages.",
        "Rangos TC: [N1-5]. Rangos DC: [N1:5] o [N1,5]. [meta:artist] usa metadatos del origen; los campos ausentes bloquean la vista previa. La sintaxis se guarda en los ajustes.",
        "Intervalos TC: [N1-5]. Intervalos DC: [N1:5] ou [N1,5]. [meta:artist] usa metadados da origem; campos ausentes bloqueiam a prévia. A sintaxe é salva com as predefinições.",
        "TC 范围：[N1-5]。DC 范围：[N1:5] 或 [N1,5]。[meta:artist] 使用数据源提供的元数据；缺失的字段会阻止预览。语法随预设保存。",
        "TC 範囲: [N1-5]。DC 範囲: [N1:5] または [N1,5]。[meta:artist] は取得済みメタデータを使用し、取得できない項目があるとプレビューを停止します。構文はプリセットに保存されます。",
        "TC 범위: [N1-5]. DC 범위: [N1:5] 또는 [N1,5]. [meta:artist]는 원본 메타데이터를 사용하며, 필드가 없으면 미리 보기가 차단됩니다. 문법은 프리셋과 함께 저장됩니다.",
        "نطاقات TC: ‏[N1-5]. نطاقات DC: ‏[N1:5] أو [N1,5]. يستخدم [meta:artist] البيانات الوصفية المتاحة من المصدر؛ تمنع الحقول المفقودة المعاينة. تُحفظ الصيغة مع الإعدادات المسبقة.",
