  "This format supports browsing and extraction. Repacking is unavailable.": [
    "Dieses Format unterstützt Durchsuchen und Entpacken. Erneutes Packen ist nicht verfügbar.",
    "Ce format permet la navigation et l’extraction. La reconstitution n’est pas disponible.",
