  "This panel": [
    "Dieser Bereich",
    "Ce volet",
    "Este panel",
    "Este painel",
    "此面板",
    "このパネル",
    "이 패널",
    "هذه اللوحة",
  ],
  "This plan uses temporary sibling names to resolve case changes, dependencies or selected folders. Each physical move is saved for recovery.":
      [
        "Dieser Plan nutzt temporäre Namen im selben Ordner, um Schreibweise, Abhängigkeiten oder ausgewählte Ordner aufzulösen. Jeder tatsächliche Verschiebevorgang wird zur Wiederherstellung gespeichert.",
        "Ce plan utilise des noms temporaires dans le même dossier pour gérer la casse, les dépendances ou les dossiers sélectionnés. Chaque déplacement est enregistré pour récupération.",
        "El plan usa nombres temporales en la misma carpeta para resolver cambios de mayúsculas, dependencias o carpetas seleccionadas. Cada movimiento se registra para recuperación.",
        "O plano usa nomes temporários na mesma pasta para resolver capitalização, dependências ou pastas selecionadas. Cada movimentação é salva para recuperação.",
        "此计划使用同一目录中的临时名称处理大小写变化、依赖关系或所选文件夹。每次实际移动都会记录以便恢复。",
        "この計画では同じフォルダー内の一時名を使い、大文字・小文字の変更、依存関係、選択したフォルダーを処理します。実際の移動をすべて復元用に記録します。",
        "이 계획은 같은 폴더의 임시 이름을 사용해 대소문자 변경, 의존 관계 또는 선택한 폴더를 처리합니다. 실제 이동은 복구를 위해 모두 기록됩니다.",
        "تستخدم هذه الخطة أسماء مؤقتة في المجلد نفسه لمعالجة تغييرات حالة الأحرف أو التبعيات أو المجلدات المحددة. يُسجّل كل نقل فعلي للاستعادة.",
      ],
  "This provider cannot automatically prove which item survived an interrupted rename. Inspect the destination using your provider before proceeding.\n\nOriginal: {0}\nObserved destination: {1}\n\nOnly confirm if the destination contains the original item. Both paths existing, or a known fingerprint mismatch, will still block recovery.":
      [
        "Dieser Anbieter kann nach einer unterbrochenen Umbenennung das verbliebene Element nicht automatisch bestimmen. Ziel vor dem Fortfahren beim Anbieter prüfen.\n\nOriginal: {0}\nBeobachtetes Ziel: {1}\n\nNur bestätigen, wenn das Ziel das Originalelement enthält. Wenn beide Pfade vorhanden sind oder ein bekannter Fingerabdruck abweicht, bleibt die Wiederherstellung blockiert.",
        "Ce fournisseur ne peut pas identifier automatiquement l’élément restant après un renommage interrompu. Vérifiez la destination chez votre fournisseur.\n\nOrigine : {0}\nDestination observée : {1}\n\nConfirmez uniquement si la destination contient l’original. Deux chemins existants ou une empreinte différente bloquent toujours la récupération.",
        "El proveedor no puede determinar automáticamente qué elemento quedó tras un renombrado interrumpido. Inspeccione el destino en el proveedor.\n\nOriginal: {0}\nDestino observado: {1}\n\nConfirme solo si el destino contiene el original. La existencia de ambas rutas o una huella distinta seguirá bloqueando la recuperación.",
        "O provedor não determina automaticamente qual item restou após uma renomeação interrompida. Inspecione o destino no provedor.\n\nOriginal: {0}\nDestino observado: {1}\n\nConfirme somente se o destino contiver o original. Ambos os caminhos existentes ou uma impressão diferente ainda bloqueiam a recuperação.",
        "此提供商无法自动确认中断重命名后保留了哪个项目。请先通过提供商检查目标。\n\n原始：{0}\n观察到的目标：{1}\n\n仅当目标包含原始项目时才确认。若两个路径均存在，或已知指纹不匹配，仍会阻止恢复。",
        "このプロバイダーでは、中断した名前変更後にどの項目が残ったかを自動判定できません。続行前にプロバイダーで保存先を確認してください。\n\n元: {0}\n検出された保存先: {1}\n\n保存先に元の項目がある場合のみ確認してください。両方のパスが存在する場合や指紋の不一致が判明した場合は、復元できません。",
        "이 공급자는 이름 변경 중단 후 어느 항목이 남았는지 자동으로 확인할 수 없습니다. 계속하기 전에 공급자에서 대상을 확인하세요.\n\n원본: {0}\n확인된 대상: {1}\n\n대상에 원본 항목이 있는 경우에만 확인하세요. 두 경로가 모두 있거나 지문 불일치가 확인되면 복구가 계속 차단됩니다.",
        "لا يستطيع هذا المزوّد إثبات العنصر الباقي بعد انقطاع إعادة التسمية تلقائيًا. افحص الوجهة لدى المزوّد قبل المتابعة.\n\nالأصلي: {0}\nالوجهة المرصودة: {1}\n\nأكّد فقط إذا احتوت الوجهة على العنصر الأصلي. سيظل وجود المسارين أو عدم تطابق البصمة مانعًا للاستعادة.",
      ],
  "This provider checks destination names before each move but does not guarantee an exclusive rename.":
