  ],
  "[N] name without the last extension; [E] extension without a dot; [C] counter; [C:4] counter with four digits; [P] original parent folder.\n[N1-4] first four characters; [N3-] from character 3; [N-4--1] last four characters. Positions start at 1.\n[YMD] and [hms] use the selected date source in CrispCloud/TC syntax. DC uses [YYYY][MM][DD] and [hh][nn][ss].\n[T1] modified; [T2] created; [T3] accessed; [T4] captured; [T5] batch time. [T4+60m] shifts the captured date one hour. [meta:artist] uses supplied metadata.\n[V:Project] uses a named variable; [G] creates a stable identifier for this preview. [C7+2:4] starts at 7, steps by 2 and uses four digits.\nTC inline case: [U] uppercase, [L] lowercase, [F] title case, [n] reset. [B0] is the parent and [B1] the grandparent.\nUse [[ and ]] for literal brackets, or [[] and []] in TC/DC syntax. External Commander content plugins are not loaded; unsupported fields produce a preview error.\nFolder names use the name mask only. A leading dot is part of a file name. Masks are applied first, then replacement, then case changes. Each transformation consumes the previous proposed name. Manual targets override the rule pipeline for that row.":
      [
        "[N] Name ohne letzte Erweiterung; [E] Erweiterung ohne Punkt; [C] Zähler; [C:4] vierstelliger Zähler; [P] ursprünglicher übergeordneter Ordner.\n[N1-4] erste vier Zeichen; [N3-] ab Zeichen 3; [N-4--1] letzte vier Zeichen. Positionen beginnen bei 1.\n[YMD] und [hms] verwenden die gewählte Datumsquelle in CrispCloud/TC. DC verwendet [YYYY][MM][DD] und [hh][nn][ss].\n[T1] geändert; [T2] erstellt; [T3] letzter Zugriff; [T4] aufgenommen; [T5] Stapelzeit. [T4+60m] verschiebt die Aufnahmezeit um eine Stunde. [meta:artist] verwendet vorhandene Metadaten.\n[V:Project] verwendet eine benannte Variable; [G] erzeugt eine stabile Kennung für diese Vorschau. [C7+2:4] beginnt bei 7, erhöht um 2 und verwendet vier Ziffern.\nTC-Schreibweise: [U] groß, [L] klein, [F] Wortanfänge groß, [n] zurücksetzen. [B0] ist der übergeordnete Ordner, [B1] dessen übergeordneter Ordner.\nWörtliche Klammern: [[ und ]] oder [[] und []] in TC/DC. Externe Commander-Inhaltsplugins werden nicht geladen; nicht unterstützte Felder erzeugen einen Vorschaufehler.\nOrdner verwenden nur die Namensmaske. Ein führender Punkt gehört zum Dateinamen. Reihenfolge: Maske, Ersetzung, Schreibweise. Jede Transformation verwendet den zuvor vorgeschlagenen Namen. Manuelle Ziele ersetzen die Regeln für diese Zeile.",
        "[N] nom sans la dernière extension ; [E] extension sans point ; [C] compteur ; [C:4] compteur à quatre chiffres ; [P] dossier parent d’origine.\n[N1-4] quatre premiers caractères ; [N3-] à partir du caractère 3 ; [N-4--1] quatre derniers caractères. Les positions commencent à 1.\n[YMD] et [hms] utilisent la source de date choisie en syntaxe CrispCloud/TC. DC utilise [YYYY][MM][DD] et [hh][nn][ss].\n[T1] modification ; [T2] création ; [T3] accès ; [T4] prise de vue ; [T5] date du lot. [T4+60m] ajoute une heure à la prise de vue. [meta:artist] utilise les métadonnées fournies.\n[V:Project] utilise une variable nommée ; [G] crée un identifiant stable pour cet aperçu. [C7+2:4] commence à 7, avance de 2 et utilise quatre chiffres.\nCasse TC : [U] majuscules, [L] minuscules, [F] initiales en majuscules, [n] réinitialisation. [B0] est le parent et [B1] le grand-parent.\nCrochets littéraux : [[ et ]], ou [[] et []] en TC/DC. Les plugins de contenu Commander externes ne sont pas chargés ; les champs non pris en charge provoquent une erreur d’aperçu.\nLes dossiers utilisent seulement le masque du nom. Un point initial fait partie du nom. Ordre : masque, remplacement, casse. Chaque transformation reçoit le nom proposé précédent. Les noms manuels remplacent les règles de la ligne.",
        "[N] nombre sin la última extensión; [E] extensión sin punto; [C] contador; [C:4] contador de cuatro dígitos; [P] carpeta superior original.\n[N1-4] primeros cuatro caracteres; [N3-] desde el carácter 3; [N-4--1] últimos cuatro caracteres. Las posiciones empiezan en 1.\n[YMD] y [hms] usan la fecha elegida en sintaxis CrispCloud/TC. DC usa [YYYY][MM][DD] y [hh][nn][ss].\n[T1] modificación; [T2] creación; [T3] acceso; [T4] captura; [T5] fecha del lote. [T4+60m] añade una hora a la captura. [meta:artist] usa los metadatos proporcionados.\n[V:Project] usa una variable con nombre; [G] crea un identificador estable para esta vista previa. [C7+2:4] empieza en 7, incrementa en 2 y usa cuatro dígitos.\nMayúsculas TC: [U] mayúsculas, [L] minúsculas, [F] iniciales mayúsculas, [n] restablecer. [B0] es la carpeta superior y [B1] la siguiente superior.\nCorchetes literales: [[ y ]], o [[] y []] en TC/DC. No se cargan plugins externos de contenido de Commander; los campos no compatibles producen un error de vista previa.\nLas carpetas usan solo la máscara del nombre. Un punto inicial forma parte del nombre. Orden: máscara, reemplazo, mayúsculas. Cada transformación recibe el nombre propuesto anterior. Los destinos manuales sustituyen las reglas de esa fila.",
        "[N] nome sem a última extensão; [E] extensão sem ponto; [C] contador; [C:4] contador com quatro dígitos; [P] pasta pai original.\n[N1-4] primeiros quatro caracteres; [N3-] a partir do caractere 3; [N-4--1] últimos quatro caracteres. As posições começam em 1.\n[YMD] e [hms] usam a origem de data escolhida na sintaxe CrispCloud/TC. DC usa [YYYY][MM][DD] e [hh][nn][ss].\n[T1] modificação; [T2] criação; [T3] acesso; [T4] captura; [T5] hora do lote. [T4+60m] acrescenta uma hora à captura. [meta:artist] usa os metadados fornecidos.\n[V:Project] usa uma variável nomeada; [G] cria um identificador estável para esta prévia. [C7+2:4] começa em 7, avança 2 e usa quatro dígitos.\nCapitalização TC: [U] maiúsculas, [L] minúsculas, [F] iniciais maiúsculas, [n] redefinir. [B0] é a pasta pai e [B1] a pasta acima dela.\nColchetes literais: [[ e ]], ou [[] e []] em TC/DC. Plugins externos de conteúdo Commander não são carregados; campos não suportados geram um erro na prévia.\nPastas usam somente a máscara do nome. Um ponto inicial faz parte do nome. Ordem: máscara, substituição, capitalização. Cada transformação recebe o nome proposto anterior. Destinos manuais substituem as regras daquela linha.",
        "[N] 不含最后一个扩展名的名称；[E] 不含点的扩展名；[C] 计数器；[C:4] 四位计数器；[P] 原始父文件夹。\n[N1-4] 前四个字符；[N3-] 从第 3 个字符开始；[N-4--1] 最后四个字符。位置从 1 开始。\n[YMD] 和 [hms] 在 CrispCloud/TC 语法中使用所选日期来源。DC 使用 [YYYY][MM][DD] 和 [hh][nn][ss]。\n[T1] 修改；[T2] 创建；[T3] 访问；[T4] 拍摄；[T5] 批次时间。[T4+60m] 将拍摄时间推迟一小时。[meta:artist] 使用已提供的元数据。\n[V:Project] 使用命名变量；[G] 为本次预览创建稳定标识符。[C7+2:4] 从 7 开始，步长为 2，使用四位数字。\nTC 内联大小写：[U] 大写，[L] 小写，[F] 每词首字母大写，[n] 重置。[B0] 是父文件夹，[B1] 是上一级父文件夹。\n字面括号用 [[ 和 ]]，TC/DC 也可用 [[] 和 []]。不加载外部 Commander 内容插件；不支持的字段会产生预览错误。\n文件夹仅使用名称掩码。开头的点属于文件名。处理顺序为掩码、替换、大小写转换。每个转换使用上一步建议的名称。手动目标名称优先于该行的规则。",
        "[N] 最後の拡張子を除く名前、[E] ドットなしの拡張子、[C] カウンター、[C:4] 4 桁のカウンター、[P] 元の親フォルダー。\n[N1-4] 最初の 4 文字、[N3-] 3 文字目以降、[N-4--1] 最後の 4 文字。位置は 1 から始まります。\nCrispCloud/TC の [YMD] と [hms] は選択した日時の取得元を使います。DC では [YYYY][MM][DD] と [hh][nn][ss] を使います。\n[T1] 更新、[T2] 作成、[T3] アクセス、[T4] 撮影、[T5] 一括処理の日時。[T4+60m] は撮影日時に 1 時間を加算します。[meta:artist] は取得済みメタデータを使います。\n[V:Project] は名前付き変数、[G] はこのプレビューで変わらない識別子です。[C7+2:4] は 7 から 2 ずつ増加し、4 桁を使います。\nTC の文字変換: [U] 大文字、[L] 小文字、[F] 各単語の先頭を大文字、[n] リセット。[B0] は親、[B1] はその親フォルダーです。\n括弧自体は [[ と ]]、TC/DC では [[] と []] も使えます。外部の Commander コンテンツプラグインは読み込まず、未対応のフィールドはプレビューエラーになります。\nフォルダーは名前マスクのみ使用します。先頭のドットは名前の一部です。処理順はマスク、置換、文字変換です。各変換は前の結果を受け取り、手動の名前はその行のルールより優先されます。",
        "[N] 마지막 확장자를 제외한 이름, [E] 점 없는 확장자, [C] 카운터, [C:4] 네 자리 카운터, [P] 원래 상위 폴더.\n[N1-4] 처음 네 글자, [N3-] 세 번째 글자부터, [N-4--1] 마지막 네 글자. 위치는 1부터 시작합니다.\nCrispCloud/TC의 [YMD]와 [hms]는 선택한 날짜 원본을 사용합니다. DC는 [YYYY][MM][DD]와 [hh][nn][ss]를 사용합니다.\n[T1] 수정, [T2] 생성, [T3] 접근, [T4] 촬영, [T5] 일괄 작업 시간. [T4+60m]는 촬영 시간에 한 시간을 더합니다. [meta:artist]는 제공된 메타데이터를 사용합니다.\n[V:Project]는 명명된 변수, [G]는 이 미리 보기에서 유지되는 식별자입니다. [C7+2:4]는 7부터 2씩 증가하며 네 자리를 사용합니다.\nTC 대소문자: [U] 대문자, [L] 소문자, [F] 각 단어 첫 글자 대문자, [n] 초기화. [B0]는 상위 폴더, [B1]은 그 위 폴더입니다.\n괄호 자체는 [[와 ]]를, TC/DC에서는 [[]와 []]도 사용합니다. 외부 Commander 콘텐츠 플러그인은 불러오지 않으며, 지원하지 않는 필드는 미리 보기 오류를 발생시킵니다.\n폴더에는 이름 마스크만 적용됩니다. 앞의 점은 이름의 일부입니다. 마스크, 바꾸기, 대소문자 순서로 적용합니다. 각 변환은 이전 결과를 사용하며 수동 이름은 해당 행의 규칙보다 우선합니다.",
        "[N] الاسم دون الامتداد الأخير؛ [E] الامتداد دون النقطة؛ [C] العداد؛ [C:4] عداد من أربع خانات؛ [P] المجلد الأب الأصلي.\n[N1-4] أول أربعة أحرف؛ [N3-] من الحرف الثالث؛ [N-4--1] آخر أربعة أحرف. تبدأ المواضع من 1.\nيستخدم [YMD] و[hms] مصدر التاريخ المحدد بصيغة CrispCloud/TC. يستخدم DC ‏[YYYY][MM][DD] و[hh][nn][ss].\n[T1] التعديل؛ [T2] الإنشاء؛ [T3] الوصول؛ [T4] الالتقاط؛ [T5] وقت الدفعة. يضيف [T4+60m] ساعة إلى وقت الالتقاط. يستخدم [meta:artist] البيانات الوصفية المتاحة.\n[V:Project] متغير مسمّى؛ [G] ينشئ معرّفًا ثابتًا لهذه المعاينة. يبدأ [C7+2:4] من 7 بزيادة 2 وأربع خانات.\nحالة الأحرف في TC: ‏[U] كبيرة، [L] صغيرة، [F] بداية كل كلمة كبيرة، [n] إعادة ضبط. [B0] المجلد الأب و[B1] المجلد الأعلى منه.\nللأقواس الحرفية استخدم [[ و]]، أو [[] و[]] في TC/DC. لا تُحمّل إضافات محتوى Commander الخارجية؛ تُظهر الحقول غير المدعومة خطأ في المعاينة.\nتستخدم المجلدات قناع الاسم فقط. النقطة الأولى جزء من الاسم. الترتيب: القناع، الاستبدال، حالة الأحرف. يستخدم كل تحويل الاسم المقترح السابق. تتجاوز الأسماء اليدوية قواعد ذلك الصف.",
      ],
